U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'
px={}
for s in U:
 d=pd.read_csv(f'{base}/{s}.csv',parse_dates=['date']).set_index('date')['close']
 px[s]=d[d.index<=pd.Timestamp('2028-05-18')]
P=pd.DataFrame(px).sort_index(); ret=P.pct_change()
v=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close']; v=v[v.index<=pd.Timestamp('2028-05-18')].reindex(P.index).ffill()
# factor is 5d contrarian return scaled by VIX level relative to its trailing 60d median; all inputs date t
variants={
 'vix_level': -ret.rolling(5).sum()*(v/v.rolling(60).median()),
 'vix_shock': -ret.rolling(5).sum()*((v/v.rolling(60).median()).clip(0.5,2.0)),
 'vix_high_gate': -ret.rolling(5).sum()*((v>v.rolling(120).quantile(.7)).astype(float)),
 'vix_low_gate': -ret.rolling(5).sum()*((v<=v.rolling(120).quantile(.7)).astype(float)),
}
for name,F in variants.items():
  rows=[]; turnovers=[]
  for i in range(len(P)-1):
    dt=P.index[i]; x=F.iloc[i]; y=P.iloc[i+1]/P.iloc[i]-1
    z=pd.concat([x,y],axis=1).dropna();
    if len(z)>=8: rows.append((dt,spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic,len(z)))
    if i>0:
      a=F.iloc[i-1].rank(pct=True); b=x.rank(pct=True); turnovers.append((a-b).abs().mean())
  a=pd.DataFrame(rows,columns=['date','ic','n']); ic=a.ic
  print(name,'dates',len(a),'avgN',round(a.n.mean(),2),'coverage',round(a.n.sum()/(len(a)*15),4),'IC',round(ic.mean(),6),'ICIR',round(ic.mean()/ic.std(ddof=1),6),'hit',round((ic>0).mean(),4),'turn',round(np.nanmean(turnovers),6),'recentIC',round(ic.tail(250).mean(),6),'recentIR',round(ic.tail(250).mean()/ic.tail(250).std(ddof=1),6))
  for h in [5,10,20]:
    yy=P.shift(-h)/P-1; rr=[]
    for i in range(len(P)-h):
      z=pd.concat([F.iloc[i],yy.iloc[i]],axis=1).dropna()
      if len(z)>=8: rr.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
    print(' ',h,round(np.nanmean(rr),6),round(np.nanmean(rr)/np.nanstd(rr,ddof=1),6),len(rr))

