from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
    try: x=get_index_daily_data(s,days=3200)
    except FileNotFoundError: x=get_stock_daily_data(s,days=3200)
    if x is not None and len(x)>=150: D[s]=x.sort_values('date').set_index('date')['close'].astype(float)
p=pd.DataFrame(D).sort_index().ffill(); r=p.pct_change()
# Volatility-state trend: medium momentum scaled by own realized volatility and
# strengthened only when short volatility is below its long volatility baseline.
v20=r.rolling(20,min_periods=15).std()*np.sqrt(20)
v60=r.rolling(60,min_periods=40).std()*np.sqrt(60)
state=(v60-v20)/v60
fac=(p.pct_change(20)/v20)*(1+0.5*state.clip(-1,1))
for h in [1,5,10,20]:
  ics=[]; cov=[]; turns=[]; recent=[]
  for i in range(61,len(p)-h):
    z=pd.concat([fac.iloc[i-1].rename('f'),(p.iloc[i+h]/p.iloc[i]-1).rename('r')],axis=1).dropna()
    if len(z)>=8:
      q=z.f.corr(z.r)
      if np.isfinite(q):
        ics.append(q); cov.append(len(z)/15)
        if i>=len(p)-250: recent.append(q)
      if i>61:
        turns.append((fac.iloc[i-1].rank(pct=True)-fac.iloc[i-2].rank(pct=True)).abs().mean())
  a=np.array(ics); rr=np.array(recent)
