import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
prices={}
for s in U:
 d=get_stock_daily_data(s,days=4000)
 if d is not None and len(d): prices[s]=d.assign(date=pd.to_datetime(d.date)).set_index('date').close.astype(float)
p=pd.DataFrame(prices).sort_index(); r=p.pct_change(); ret=p.pct_change(60)
neg=r.clip(upper=0); down=np.sqrt((neg**2).rolling(60,min_periods=40).mean())*np.sqrt(60)
dd=p/p.rolling(120,min_periods=80).max()-1
f=ret/(down+1e-8)*(1+dd.clip(-0.5,0)); out={}
for h in [1,5,10,20]:
 vals=[]; ns=[]; fw=p.pct_change(h).shift(-h)
 for i in range(len(p)-h):
  z=pd.concat([f.iloc[i],fw.iloc[i]],axis=1).dropna()
  if len(z)>=8: vals.append(z.iloc[:,0].corr(z.iloc[:,1])); ns.append(len(z))
 q=pd.Series(vals).dropna(); ic=q.mean(); ir=ic/q.std(ddof=1)
 print(f'{h}d dates={len(q)} avgN={np.mean(ns):.2f} IC={ic:.6f} ICIR={ir:.6f} hit={(q>0).mean():.4f}'); out[h]=q
valid=f.notna().sum(axis=1)/len(U); rank=f.rank(axis=1,pct=True)
print(f'coverage={valid.mean():.4f} turnover={rank.diff().abs().mean(axis=1).mean()/2:.6f} total_dates={len(p)} avg_names={f.notna().sum(axis=1).mean():.2f}')
for n in [250,500]:
 q=out[5].tail(n); print(f'recent{n} IC={q.mean():.6f} ICIR={q.mean()/q.std(ddof=1):.6f} dates={len(q)}')
print('period',p.index.min().date(),p.index.max().date())

