 a=pd.concat([fac.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(a)>=8:z.append((dt,a.iloc[:,0].corr(a.iloc[:,1],method='spearman'),len(a)))
z=pd.DataFrame(z,columns=['date','ic','n']).set_index('date')
for n in [250,500]:
 q=z.tail(n).ic; print(f'recent{n} IC={q.mean():.6f} ICIR={q.mean()/q.std(ddof=1):.6f}')
