import os, numpy as np, pandas as pd
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'; end=pd.Timestamp('2031-02-19')
d={s:pd.read_csv(os.path.join(base,s+'.csv'),parse_dates=['date']).sort_values('date').set_index('date') for s in U}
C=pd.DataFrame({s:x.close.astype(float) for s,x in d.items()}).sort_index().loc[:end].ffill(); r=C.pct_change()
# Relative-strength quality: 20d return in excess of contemporaneous cross-asset median,
# multiplied by persistence (share of positive daily returns), then volatility scaled.
ret20=C.pct_change(20); med=ret20.median(axis=1); excess=ret20.sub(med,axis=0)
persist=r.rolling(20,min_periods=15).apply(lambda x: np.mean(x>0),raw=True)
vol=r.rolling(40,min_periods=25).std()*np.sqrt(252)
raw=(excess/vol)*(0.5+persist)
sig=raw.rank(axis=1,pct=True).shift(1)
rows=[]
for i in range(len(C)-10):
 z=pd.concat([sig.iloc[i],C.iloc[i+10]/C.iloc[i]-1],axis=1).dropna()
 if len(z)>=8: rows.append((C.index[i],len(z),spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic))
a=pd.DataFrame(rows,columns=['date','n','ic']);
def met(q): return (q.ic.mean(),q.ic.mean()/q.ic.std(ddof=1)*np.sqrt(len(q)),(q.ic>0).mean()) if len(q)>1 else (np.nan,np.nan,np.nan)
for label,q in [('full',a),('recent365',a[a.date>=a.date.max()-pd.Timedelta(days=365)]),('recent730',a[a.date>=a.date.max()-pd.Timedelta(days=730)])]: print(label,'dates',len(q),'avgN',round(q.n.mean(),2),'IC %.6f ICIR %.6f hit %.4f'%met(q))
print('coverage %.4f turnover %.6f instruments %d cutoff %s'%(sig.notna().mean().mean(),sig.diff().abs().mean(axis=1).mean(),len(U),C.index[-1].date()))
# regime split by median cross-sectional 20d return sign
for name,q in [('risk_on',a[med.reindex(a.date).values>0]),('risk_off',a[med.reindex(a.date).values<=0])]: print(name,'dates',len(q),'IC %.6f ICIR %.6f'%met(q)[:2])

import os,numpy as np,pandas as pd
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'; d={s:pd.read_csv(os.path.join(base,s+'.csv'),parse_dates=['date']).set_index('date').sort_index() for s in U}
C=pd.DataFrame({s:x.close.astype(float) for s,x in d.items()}).sort_index().loc[:'2031-04-02'].ffill(); r=C.pct_change()
# Residual short-term reversal: subtract cross-sectional/common 5d move from each asset 5d return, negate residual.
ret=C.pct_change(5); common=ret.median(axis=1); raw=-(ret-common[:,None]); sig=raw.rank(axis=1,pct=True).shift(1)
for h in [5,10,20]:
 rows=[]
 for i in range(len(C)-h):
  z=pd.concat([sig.iloc[i],C.iloc[i+h]/C.iloc[i]-1],axis=1).dropna()
  if len(z)>=8: rows.append((C.index[i],len(z),spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic))
 a=pd.DataFrame(rows,columns=['date','n','ic'])
 def met(q): return q.ic.mean(),q.ic.mean()/q.ic.std(ddof=1)*np.sqrt(len(q))
 for lab,q in [('full',a),('recent365',a[a.date>=a.date.max()-pd.Timedelta(days=365)]),('recent730',a[a.date>=a.date.max()-pd.Timedelta(days=730)]),('recent1095',a[a.date>=a.date.max()-pd.Timedelta(days=1095)])]: print(f'h{h} {lab}: dates={len(q)} avgN={q.n.mean():.2f} IC={met(q)[0]:.6f} ICIR={met(q)[1]:.6f} hit={(q.ic>0).mean():.4f}')
print(f'coverage={sig.notna().mean().mean():.4f} turnover={sig.diff().abs().mean(axis=1).mean():.6f} instruments={len(U)} cutoff={C.index[-1].date()}')

import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cut=pd.Timestamp('2031-04-16')
px={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').close.loc[:cut] for s in U}
dates=sorted(set.intersection(*[set(x.index) for x in px.values()]))
P=pd.DataFrame({s:px[s].reindex(dates) for s in U}); r=P.pct_change()
# Lagged residual reversal, continuously favored when cross-sectional 1d dispersion is low.
disp=r.std(axis=1).rolling(20,min_periods=10).mean()
gate=(1/(disp+disp.rolling(120,min_periods=40).median())).shift(1)
base=-(P.pct_change(5).sub(P.pct_change(5).median(axis=1),axis=0)).shift(1)
f=base.mul(gate,axis=0)
def run(H,start=0):
 a=[];ns=[]
 for i in range(start,len(P)-H-1):
  x=f.iloc[i]; y=P.iloc[i+1+H]/P.iloc[i+1]-1; ok=x.notna()&y.notna(); ns.append(int(ok.sum()))
  if ok.sum()>=8 and x[ok].nunique()>1 and y[ok].nunique()>1:
   z=spearmanr(x[ok],y[ok]).statistic
   if np.isfinite(z): a.append(z)
 a=np.asarray(a)
 return len(a),float(a.mean()),float(a.mean()/a.std(ddof=1)),float((a>0).mean()),float(np.mean(ns)),float(np.mean(f.notna().mean(axis=1)))
print('cutoff',cut.date(),'dates',len(P),'assets',len(U))
for H in [1,5,10,20]: print('H',H,run(H))
for n in [365,730,1095]: print('recent',n,'h5',run(5,max(0,len(P)-n-6)))
print('rank turnover',float((f.rank(axis=1,pct=True).diff().abs().mean(axis=1)>0.10).mean()))

