  z=[]; y=[]
  for s in U:
   if dt in xs[s].index:
    a=xs[s].loc[dt,'f']; b=xs[s].loc[dt,'r'+str(h)]
    if np.isfinite(a) and np.isfinite(b): z.append(a);y.append(b)
