mom=p.shift(1).pct_change(30); down=r.where(r<0,0).rolling(30,min_periods=20).std().shift(1)
f=(mom/(down+1e-8)).replace([np.inf,-np.inf],np.nan)
fr=p.shift(-10)/p-1; rows=[]
for dt in f.index:
